entries[162198] = { ["name"] = "Razorguard Mechshades", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nGearspring Parts (100)\nOptional Reagents:\nOptional Reagent Slot (#50) , Linkgrease Locksprocket (#238)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nRazorguard Mechshades\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)Head Plate\n13 Armor\n+5 [Strength or Intellect]+7 Stamina\nDurability 100 / 100\nUse: Allows you to look far into the distance.\n35\nRequires Draenor Engineering\n(1)" }
entries[162199] = { ["name"] = "Shrediron's Shredder", ["text"] = "3 sec cast\nTools: Gyromatic Micro-Adjustor\nWithout Profession:\nReagents:\nGearspring Parts (100)\nOptional Reagents:\nOptional Reagent Slot (#50) , True Iron Trigger (#239)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nShrediron's Shredder\nBinds when equipped\nUnique-Equipped: Warlords Crafted (3)Ranged Gun\n7 - 13 Damage Speed 3.00\n(3.3 damage per second)\n+5 Agility\n+7 Stamina\nDurability 120 / 120\n35\n\"To engineers, a work of art. To hunters, a tool for the art of killing.\"" }
entries[162202] = { ["name"] = "Oglethorpe's Missile Splitter", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nWithout Profession:\nReagents:\nGearspring Parts (20)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nOglethorpe's Missile Splitter\nUse: Permanently attaches a special device to a ranged weapon, sometimes increases haste by 115 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level 320.\n35" }
entries[162203] = { ["name"] = "Megawatt Filament", ["text"] = "2 sec cast\nTools: Arclight Spanner\nWithout Profession:\nReagents:\nGearspring Parts (20)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nMegawatt Filament\nUse: Permanently attaches an electrified device to a ranged weapon, sometimes increasing Critical Strike by 115 for 12 sec when dealing damage with ranged attacks.\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level 320.\n35\n\"Everything is better when it's electrified.\"" }
entries[162204] = { ["name"] = "Goblin Glider Kit", ["text"] = "2 sec cast\nTools: Arclight Spanner\nReagents:\nTrue Iron Ore (8), Sumptuous Fur (5)\nVendor:\nZaren Hoffle\nItem:\nDraenor Engineering\nCost:\n100\nZone:\nLunarfall\n\nVendor:\nSean Catchpole\nItem:\nDraenor Engineering\nCost:\n100\nZone:\nAshran\n\n(5)\nUse: Reduces your falling speed for 2 min. (3 Min Cooldown)" }
entries[162205] = { ["name"] = "Findle's Loot-a-Rang", ["text"] = "2 sec cast\nTools: Blacksmith Hammer\nWithout Profession:\nReagents:\nGearspring Parts (50)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nFindle's Loot-A-Rang\nBinds when used\nToy\nUse: Retrieves the loot from a nearby corpse. Can only be used in Draenor. (3 Sec Cooldown)" }
entries[162206] = { ["name"] = "World Shrinker", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nGearspring Parts (50)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nWorld Shrinker\nToy\nUse: Shrinks the entire world for 5 min or until you attack. (15 Min Cooldown)\nRequires Draenor Engineering\n(1)\n\"Overuse may result in permanent shrinkage.\"" }
entries[162207] = { ["name"] = "Stealthman 54", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nReagents:\nBlackrock Ore (2), True Iron Ore (2), Nagrand Arrowbloom (2)\nVendor:\nZaren Hoffle\nItem:\nDraenor Engineering\nCost:\n100\nZone:\nLunarfall\n\nVendor:\nSean Catchpole\nItem:\nDraenor Engineering\nCost:\n100\nZone:\nAshran\n\n(5)\nUse: Cloaks the user in a stealth field for as long as they stand still. Cannot be used in combat. The field lasts for up to 6 sec. after moving.\n\nThe Stealthman shares a cooldown with non-healing potions. Ineffective above level 49. (5 Min Cooldown)\n35\n\"Invisibility is for suckers!\"" }
entries[162208] = { ["name"] = "Ultimate Gnomish Army Knife", ["text"] = "2 sec cast\nReagents:\nGearspring Parts (5)\nUltimate Gnomish Army Knife\n+10 Draenor Mining Skill.\n+10 Draenor Herbalism Skill.\n+10 Draenor Skinning Skill.\n\"Includes every profession tool.\"" }
entries[162209] = { ["name"] = "Mechanical Axebeak", ["text"] = "3.5 sec cast\nTools: Arclight Spanner\nWithout Profession:\nReagents:\nGearspring Parts (50)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nMechanical Axebeak\nUse: Teaches you how to summon this companion.\nSummons and dismisses your Mechanical Axebeak.\n1 to 80 ( 80)" }
entries[162210] = { ["name"] = "Lifelike Mechanical Frostboar", ["text"] = "3.5 sec cast\nTools: Gyromatic Micro-Adjustor\nWithout Profession:\nReagents:\nGearspring Parts (50), Sumptuous Fur (40)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nLifelike Mechanical Frostboar\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss your lifelike mechanical boar.\n1 to 80 ( 80)" }
entries[162214] = { ["name"] = "Personal Hologram", ["text"] = "2 sec cast\nTools: Gyromatic Micro-Adjustor\nWithout Profession:\nReagents:\nGearspring Parts (50)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nPersonal Hologram\nBinds when used\nToy\nUse: Create a temporary hologram of yourself for 1 min. (5 Min Cooldown)\n\"Image may react to some emotes.\"" }
entries[162216] = { ["name"] = "Wormhole Centrifuge", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Arclight Spanner\nReagents:\nGearspring Parts (50)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nWormhole Centrifuge\nBinds when used\nToy\nUse: Creates a spinning wormhole the Engineer can use to travel around Draenor. (4 Hrs Cooldown)\n34\nRequires Draenor Engineering\n(1)" }
entries[162217] = { ["name"] = "Swapblaster", ["text"] = "2 sec cast\nTools: Arclight Spanner\nWithout Profession:\nReagents:\nGearspring Parts (50), Temporal Crystal\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nSwapblaster\nBinds when used\nUse: Swaps your location with another party member. Cannot be used in combat. (1 Min Cooldown)\n\"Warning: Swapping with someone using a Neural Silencer is highly dangerous.\"" }
entries[162218] = { ["name"] = "Blingtron 5000", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nGearspring Parts (100)\nVendor:\nNik Steelrings\nZone:\nWarspear\nCost:\n1\n\nBlingtron 5000\nBinds when picked up\nToy\nUse: Assembles the upgraded Blingtron 5000, a savage, yet generous, robot. While he will give out gifts to players once per day, he will also fight other Blingtron units to the death. (4 Hrs Cooldown)\nRequires Draenor Engineering\n(1)" }
